namespace {
HostWriteExecutor::MutationOutcome fail(const QString&c,const QString&m,bool refresh=false){HostWriteExecutor::MutationOutcome o;o.error={c,m,false};if(refresh)o.error.conflict={{"refreshRequired",true}};return o;}
QString minifigNumber(const QSqlDatabase&db,int id){for(const auto&x:MinifigCatalogRepository(db).identifiersForMinifig(id))if(x.provider.compare("Rebrickable",Qt::CaseInsensitive)==0)return x.externalId;return{};}
QString setNumber(const QSqlDatabase&db,int id){auto x=SetCatalogRepository(db).getById(id);return x?x->setNumber():QString();}
QJsonObject detail(const QSqlDatabase&db,const CollectionItem&i){QString set,fig,path;if(i.setCatalogId>0){auto x=SetCatalogRepository(db).getById(i.setCatalogId);if(x)set=x->setNumber();}if(i.minifigCatalogId>0)fig=minifigNumber(db,i.minifigCatalogId);if(i.storageLocationId>0){auto x=StorageLocationRepository(db).getById(i.storageLocationId);if(x)path=x->name();}return{{"collectionItemId",i.id},{"workspaceId",i.workspaceId},{"type",collectionItemTypeToString(i.type)},{"setNumber",set},{"minifigNumber",fig},{"sourceBuildId",i.sourceBuildId},{"state",collectionItemStateToString(i.state)},{"condition",collectionItemConditionToString(i.condition)},{"completeness",collectionItemCompletenessToString(i.completeness)},{"storageId",i.storageLocationId},{"storagePath",path},{"nickname",i.nickname},{"notes",i.notes},{"allowPartsSource",i.allowPartsSource},{"active",i.isActive},{"createdUtc",i.createdUtc.toUTC().toString(Qt::ISODateWithMs)},{"modifiedUtc",i.modifiedUtc.toUTC().toString(Qt::ISODateWithMs)}};}
bool matches(const QSqlDatabase&db,const CollectionItem&i,const RemoteCollectionMutationDto::ExpectedState&e){return i.modifiedUtc.toUTC().toString(Qt::ISODateWithMs)==e.modifiedUtc&&i.isActive==e.active&&collectionItemTypeToString(i.type)==e.type&&setNumber(db,i.setCatalogId)==e.setNumber&&minifigNumber(db,i.minifigCatalogId)==e.minifigNumber&&i.sourceBuildId==e.sourceBuildId&&collectionItemStateToString(i.state)==e.state&&collectionItemConditionToString(i.condition)==e.condition&&collectionItemCompletenessToString(i.completeness)==e.completeness&&i.storageLocationId==e.storageId&&i.nickname==e.nickname&&i.notes==e.notes;}
HostWriteExecutor::MutationOutcome map(const QSqlDatabase&db,const CollectionItemService::Result&r){if(!r.success){QString code="INVALID_ARGUMENT";if(r.error==CollectionItemService::Error::ItemNotFound||r.error==CollectionItemService::Error::CatalogItemNotFound||r.error==CollectionItemService::Error::SourceBuildNotFound)code="NOT_FOUND";else if(r.error==CollectionItemService::Error::SourceBuildAlreadyUsed)code="CONFLICT";else if(r.error==CollectionItemService::Error::DatabaseFailure)code="INTERNAL_ERROR";return fail(code,r.message,code=="CONFLICT");}HostWriteExecutor::MutationOutcome o;o.success=true;o.authoritative={{"item",detail(db,r.item)}};o.publicationWorkflow=HostMutationPublicationService::Workflow::Collection;o.publicationScope.workspaceId=r.item.workspaceId;o.publicationScope.collectionItemId=r.item.id;return o;}
HostWriteExecutor::MutationOutcome mapPartsSource(const CollectionItemService::Result&r){if(!r.success)return map(QSqlDatabase(),r);HostWriteExecutor::MutationOutcome o;o.success=true;o.authoritative={{"item",QJsonObject{{"collectionItemId",r.item.id},{"allowPartsSource",r.item.allowPartsSource},{"modifiedUtc",r.item.modifiedUtc.toUTC().toString(Qt::ISODateWithMs)}}}};o.publicationWorkflow=HostMutationPublicationService::Workflow::Collection;o.publicationScope.workspaceId=r.item.workspaceId;o.publicationScope.collectionItemId=r.item.id;return o;}
HostWriteExecutor::MutationOutcome disassemble(const QSqlDatabase&db,const RemoteCollectionMutationDto::Request&r,const CollectionItem&item){const auto portable=CollectionDisassemblyPlanService(db).preview(int(r.workspaceId),item.id);if(!portable.success)return fail(portable.errorCode,portable.message,true);if(portable.plan.planId!=r.planId)return fail("STALE_VERSION","The Collection disassembly plan changed on the Host. Refresh and try again.",true);if(r.returns.size()!=portable.plan.rows.size())return fail("STALE_VERSION","The Collection disassembly return plan is incomplete. Refresh and try again.",true);QHash<qint64,RemoteCollectionMutationDto::DisassemblyReturn> selected;for(const auto&row:r.returns)selected.insert(row.rowIndex,row);for(const auto&row:portable.plan.rows){if(!selected.contains(row.rowIndex)||selected.value(row.rowIndex).quantity!=row.quantity)return fail("STALE_VERSION","The Collection disassembly quantities changed on the Host. Refresh and try again.",true);if(!StorageLocationRepository(db).isValidInventoryDestination(item.workspaceId,int(selected.value(row.rowIndex).storageId)))return fail("CONFLICT","A selected Host Storage destination is no longer available.",true);}HostWriteExecutor::MutationOutcome out;if(item.sourceBuildId>0){const auto source=BuildLifecycleService(db).linkedCollectionDisassemblyReturnPlan(item.id);if(!source.success)return fail("STALE_VERSION",source.message+QStringLiteral(" Refresh and try again."),true);if(source.rows.size()!=portable.plan.rows.size())return fail("STALE_VERSION","The linked Build return plan changed on the Host. Refresh and try again.",true);QList<BuildLifecycleService::DisassemblyReturn> returns;for(int i=0;i<source.rows.size();++i){auto row=source.rows.at(i);row.storageLocationId=int(selected.value(i+1).storageId);row.quantity=selected.value(i+1).quantity;returns.append(row);}const auto result=BuildLifecycleService(db).disassembleInCurrentTransaction(item.sourceBuildId,returns,CollectionItemState::Unassembled);if(!result.success)return fail(result.error==BuildLifecycleService::Error::DatabaseFailure?"INTERNAL_ERROR":"STALE_VERSION",result.message,true);out.publicationWorkflow=HostMutationPublicationService::Workflow::BuildDisassembly;out.publicationScope.buildId=item.sourceBuildId;out.publicationScope.inventoryChanged=true;out.publicationScope.collectionChanged=true;}else{const auto source=CollectionDisassemblyService(db).preview(item.id);if(!source.success||source.rows.size()!=portable.plan.rows.size())return fail("STALE_VERSION","The catalog return plan changed on the Host. Refresh and try again.",true);QList<CollectionDisassemblyService::DestinationAssignment> assignments;for(int i=0;i<source.rows.size();++i){const auto&row=source.rows.at(i);assignments.append({row.partId,row.colorId,row.quantity,int(selected.value(i+1).storageId)});}const auto result=CollectionDisassemblyService(db).disassembleInCurrentTransaction(item.id,item.modifiedUtc,assignments);if(!result.success)return fail(result.error==CollectionDisassemblyService::Error::DatabaseFailure?"INTERNAL_ERROR":result.error==CollectionDisassemblyService::Error::Stale?"STALE_VERSION":"CONFLICT",result.message,true);out.publicationWorkflow=HostMutationPublicationService::Workflow::CollectionDisassembly;}const auto updated=CollectionRepository(db).getById(item.id);if(!updated)return fail("INTERNAL_ERROR","The Host could not reload the disassembled Collection item.");out.success=true;out.authoritative={{"item",detail(db,*updated)}};out.publicationScope.workspaceId=item.workspaceId;out.publicationScope.collectionItemId=item.id;return out;}
}
HostWriteExecutor::Mutation HostCollectionMutationService::createMutation(const QString&op,const RemoteMutationDto::Metadata&md,RemoteMutationDto::Error*error){RemoteCollectionMutationDto::Request r;if(!RemoteCollectionMutationDto::fromMetadata(op,md,&r,error))return{};return[op,r](const QSqlDatabase&db){CollectionItemService service(db);if(op=="collection.add"){CollectionItemService::Result result;if(r.sourceType=="SetCatalog"){bool ok=false;auto rows=SetCatalogRepository(db).getExactMatchesBySetNumber(r.setNumber,&ok);if(!ok)return fail("INTERNAL_ERROR","The Host could not resolve the Set identity.");if(rows.size()!=1)return fail(rows.isEmpty()?"NOT_FOUND":"CONFLICT","The Rebrickable Set identity is unavailable or ambiguous.");result=service.createSetInCurrentTransaction(r.workspaceId,rows.first().id(),collectionItemStateFromString(r.state),r.storageId,0,r.nickname,r.notes,collectionItemConditionFromString(r.condition),collectionItemCompletenessFromString(r.completeness));}else if(r.sourceType=="MinifigCatalog"){bool ok=false;auto x=MinifigCatalogRepository(db).getByExternalIdentifier("Rebrickable",r.minifigNumber,&ok);if(!ok)return fail("INTERNAL_ERROR","The Host could not resolve the Minifig identity.");if(!x)return fail("NOT_FOUND","The Rebrickable Minifig identity is unavailable.");result=service.createMinifigInCurrentTransaction(r.workspaceId,x->id(),collectionItemStateFromString(r.state),r.storageId,0,r.nickname,r.notes,collectionItemConditionFromString(r.condition),collectionItemCompletenessFromString(r.completeness));}else if(r.sourceType=="Build")result=service.createFromBuildInCurrentTransaction(r.workspaceId,r.buildId,collectionItemStateFromString(r.state),r.storageId,r.nickname,r.notes,collectionItemConditionFromString(r.condition),collectionItemCompletenessFromString(r.completeness));else return fail("INVALID_ARGUMENT","The Collection source type is unsupported.");return map(db,result);}std::optional<CollectionItem> item;if(!CollectionRepository(db).tryGetById(r.collectionItemId,item))return fail("INTERNAL_ERROR","The Host could not read the Collection item.");if(!item||item->workspaceId!=r.workspaceId)return fail("NOT_FOUND","The Collection item was not found in this Workspace.");if(op=="collection.partsSource.set"){if(item->type!=CollectionItemType::Set)return fail("INVALID_ARGUMENT","Only Set Collection items can be used as parts sources.");if(item->modifiedUtc.toUTC().toString(Qt::ISODateWithMs)!=r.expected.modifiedUtc||item->allowPartsSource!=r.expected.allowPartsSource)return fail("STALE_VERSION","The Collection item changed. Refresh and try again.",true);return mapPartsSource(service.updateDetailsInCurrentTransaction(item->id,item->state,item->storageLocationId,item->nickname,item->notes,r.allowPartsSource,item->condition,item->completeness));}if(!matches(db,*item,r.expected))return fail("STALE_VERSION","The Collection item changed. Refresh and try again.",true);if(op=="collection.disassemble")return disassemble(db,r,*item);if(op=="collection.edit")return map(db,service.updateDetailsInCurrentTransaction(item->id,collectionItemStateFromString(r.state),r.storageId,r.nickname,r.notes,item->allowPartsSource,collectionItemConditionFromString(r.condition),collectionItemCompletenessFromString(r.completeness)));return map(db,service.setActiveInCurrentTransaction(item->id,r.desiredActive));};}
